const payload = $('Chuẩn hóa dữ liệu publish').first().json;
const media = Array.isArray(payload.media) ? payload.media : [];
const mediaUrls = Array.isArray(payload.mediaUrls) ? payload.mediaUrls : [];
const video = media.find((item) => String(item?.mimeType || '').startsWith('video/'))
  || media.find((item) => item?.videoUrl || /video/i.test(String(item?.fileName || '')));
if (!video) throw new Error('Missing YouTube video media');

// media[].fileId / media[].id are app database IDs. Extract the Google Drive ID from its URL.
const sourceUrl = String(video.url || video.videoUrl || mediaUrls.find((url) => typeof url === 'string' && url.trim()) || '');
let videoFileId = '';
try {
  videoFileId = new URL(sourceUrl).searchParams.get('id') || '';
} catch {
  const match = sourceUrl.match(/[?&]id=([^&]+)/);
  videoFileId = match ? decodeURIComponent(match[1]) : '';
}
if (!videoFileId) throw new Error(`Google Drive file ID was not found in video URL: ${sourceUrl || '(empty URL)'}`);

return {
  json: {
    ...payload,
    video_file_id: videoFileId,
    youtube_title: String(payload.title || 'EPCB Video').slice(0, 100),
    youtube_description: payload.description || payload.content,
  },
};
